def as_bool_str(value) -> str:
    """
    Convert Viash boolean-like values to SDePER CLI boolean string.
    """
    if isinstance(value, bool):
        return "true" if value else "false"

    if isinstance(value, str):
        value_lower = value.strip().lower()
        if value_lower in {"true", "t", "1", "yes", "y"}:
            return "true"
        if value_lower in {"false", "f", "0", "no", "n"}:
            return "false"

    raise ValueError(f"Cannot interpret boolean value: {value!r}")


def get_count_layer(adata_obj: ad.AnnData):
    """
    Prefer raw counts from layers['counts']; otherwise fall back to X.
    """
    if "counts" in adata_obj.layers:
        return adata_obj.layers["counts"]
    return adata_obj.X


def counts_to_obs_by_gene_df(adata_obj: ad.AnnData) -> pd.DataFrame:
    """
    Convert AnnData counts to DataFrame with rows = observations and columns = genes.

    Important:
    SDePER expects nUMI/count matrices in this orientation:
      - spatial.csv   = spots x genes
      - scrna_ref.csv = cells x genes

    AnnData stores X/layers as obs x var, so we intentionally do NOT transpose.
    """
    X = get_count_layer(adata_obj)

    if sparse.issparse(X):
        X = X.toarray()

    X = np.asarray(X)

    if X.shape != (adata_obj.n_obs, adata_obj.n_vars):
        raise ValueError(
            "Unexpected count matrix shape. "
            f"Got {X.shape}, expected {(adata_obj.n_obs, adata_obj.n_vars)}."
        )

    return pd.DataFrame(
        X,
        index=adata_obj.obs_names.astype(str),
        columns=adata_obj.var_names.astype(str),
    )


def choose_cell_type_column(sc: ad.AnnData) -> str:
    """
    Find cell-type annotation column in the single-cell reference.

    The OpenProblems API requires obs['cell_type'], but fallback names are kept
    only to make local debugging easier.
    """
    candidates = [
        "cell_type",
        "celltype",
        "label",
        "labels",
        "annotation",
        "cell_annotation",
    ]

    for col in candidates:
        if col in sc.obs.columns:
            return col

    raise KeyError(
        "Could not find a cell-type annotation column in input_single_cell.obs. "
        f"Available columns: {list(sc.obs.columns)}"
    )


def get_cell_type_names(st: ad.AnnData, sc: ad.AnnData, cell_type_col: str) -> list[str]:
    """
    Get expected cell-type order for OpenProblems output.

    OpenProblems uses uns['cell_type_names'] to define the expected column order
    of obsm['proportions_pred'].
    """
    if "cell_type_names" in st.uns:
        return list(map(str, st.uns["cell_type_names"]))

    return sorted(map(str, pd.unique(sc.obs[cell_type_col].astype(str))))


def print_csv_shape(path: Path, name: str) -> None:
    """
    Print CSV shape for debugging.
    """
    try:
        df_head = pd.read_csv(path, index_col=0, nrows=3)
        n_cols = df_head.shape[1]
        with path.open("r") as handle:
            n_rows = sum(1 for _ in handle) - 1
        print(f"{name}: {n_rows} rows x {n_cols} columns -> {path}", flush=True)
    except Exception as exc:
        print(f"Could not inspect {name}: {exc}", flush=True)


def read_sdeper_output(prop_file: Path) -> pd.DataFrame:
    """
    Read SDePER deconvolution output.

    Expected output:
      celltype_proportions.csv

    Expected orientation:
      rows = spots, columns = cell types.
    """
    if not prop_file.exists():
        print("Files generated in SDePER working directory:", flush=True)
        for p in sorted(prop_file.parent.iterdir()):
            print(f"  {p.name}", flush=True)
        raise FileNotFoundError(f"Expected SDePER output file not found: {prop_file}")

    pred = pd.read_csv(prop_file, index_col=0)
    pred.index = pred.index.astype(str)
    pred.columns = pred.columns.astype(str)

    return pred



# options
use_cvae = as_bool_str(par.get("use_cvae", True))
n_cores = int(par.get("n_cores", 20))


print('Reading input files', flush=True)
input_single_cell = ad.read_h5ad(par['input_single_cell'])
input_spatial_masked = ad.read_h5ad(par['input_spatial_masked'])


print('Preprocess data', flush=True)
# ... preprocessing ...
cell_type_col = choose_cell_type_column(input_single_cell)
cell_type_names = get_cell_type_names(input_spatial_masked, input_single_cell, cell_type_col)

print(f"Using single-cell cell-type column: {cell_type_col}", flush=True)
print(f"Number of expected cell types: {len(cell_type_names)}", flush=True)
print(f"SDePER --use_cvae: {use_cvae}", flush=True)
    

with tempfile.TemporaryDirectory() as tmp:
    tmpdir = Path(tmp)

    spatial_csv = tmpdir / "spatial.csv"
    scrna_ref_csv = tmpdir / "scrna_ref.csv"
    scrna_anno_csv = tmpdir / "scrna_anno.csv"

    print("Writing SDePER input CSV files", flush=True)

    # Important:
    # Do NOT transpose.
    # SDePER expects:
    #   spatial.csv   = spots x genes
    #   scrna_ref.csv = cells x genes
    spatial_df = counts_to_obs_by_gene_df(input_spatial_masked)
    scrna_ref_df = counts_to_obs_by_gene_df(input_single_cell)

    spatial_df.to_csv(spatial_csv)
    scrna_ref_df.to_csv(scrna_ref_csv)

    # SDePER can match scRNA-seq reference and cell-type annotations by cell names.
    # We therefore do not enforce identical row order beyond exporting the same cell names.
    scrna_anno_df = pd.DataFrame(
        {"cell_type": input_single_cell.obs[cell_type_col].astype(str).values},
        index=input_single_cell.obs_names.astype(str),
    )
    scrna_anno_df.to_csv(scrna_anno_csv)

    print_csv_shape(spatial_csv, "spatial.csv")
    print_csv_shape(scrna_ref_csv, "scrna_ref.csv")
    print_csv_shape(scrna_anno_csv, "scrna_anno.csv")
    
    print('Train model', flush=True)
    # ... train model ...

    print("Running SDePER", flush=True)
    cmd = [
        "runDeconvolution",
        "-q", str(spatial_csv),
        "-r", str(scrna_ref_csv),
        "-c", str(scrna_anno_csv),
        "--use_cvae", use_cvae,
        "--n_cores", str(n_cores),
    ]

    print("Command:", " ".join(cmd), flush=True)
    subprocess.run(cmd, cwd=tmpdir, check=True)

    prop_file = Path("/data") / "celltype_proportions.csv"
    pred = read_sdeper_output(prop_file)


print('Generate predictions', flush=True)
# ... generate predictions ...
expected_cell_types = list(input_spatial_masked.uns["cell_type_names"])

# Align cell-type columns
missing_cell_types = set(expected_cell_types) - set(pred.columns)
if missing_cell_types:
    raise ValueError(
        "SDePER output is missing expected cell-type columns: "
        f"{sorted(missing_cell_types)}"
    )

pred = pred.loc[:, expected_cell_types]

# Match only predicted spots
common_spots = pred.index.intersection(input_spatial_masked.obs_names)

if len(common_spots) == 0:
    raise ValueError(
        "No overlapping spot names between SDePER output and input_spatial.obs_names. "
        f"Example SDePER output spots: {list(pred.index[:10])}; "
        f"example input_spatial spots: {list(input_spatial_masked.obs_names[:10])}."
    )

n_filtered = input_spatial_masked.n_obs - len(common_spots)
if n_filtered > 0:
    print(
        f"SDePER returned predictions for {len(common_spots)} / {input_spatial_masked.n_obs} spots. "
        f"{n_filtered} spots were not included in the SDePER output, likely due to method-specific filtering.",
        flush=True,
    )

# Preserve SDePER output order, we also need to subset input, otherwise shape NOT match error
pred = pred.loc[common_spots, expected_cell_types]
input_spatial_out = input_spatial_masked[common_spots, :].copy()

input_spatial_out.obsm["proportions_pred"] = pred.values


print("Write output AnnData to file", flush=True)
output = ad.AnnData(
    obs=input_spatial_out.obs[[]],
    var=input_spatial_out.var[[]],
    obsm={
        "spatial": input_spatial_out.obsm["spatial"],
        "proportions_pred": input_spatial_out.obsm["proportions_pred"],
    },
    layers={
        "counts": input_spatial_out.layers["counts"],
    },
    uns={
        "cell_type_names": input_spatial_masked.uns["cell_type_names"],
        "dataset_id": input_spatial_masked.uns["dataset_id"],
        "method_id": meta["name"],
    },
)

output.write_h5ad(par['output'], compression='gzip')
print("Done.", flush=True)
print(f"Output written to: {output}", flush=True)
print(f"method_id: {output.uns['method_id']}", flush=True)
print(f"proportions_pred shape: {output.obsm['proportions_pred'].shape}", flush=True)
